package com.abcvpn.admin;
import static org.assertj.core.api.Assertions.assertThat;import static org.mockito.Mockito.*;
import java.math.BigDecimal;import java.time.Instant;import java.util.List;import java.util.Optional;import java.util.UUID;import org.junit.jupiter.api.Test;
import com.abcvpn.entity.Tariff;import com.abcvpn.entity.User;import com.abcvpn.enumeration.SourceType;import com.abcvpn.repository.*;import com.abcvpn.service.*;
class AdminServiceTest {
 @Test void banAlsoRevokesVpnAccess(){UserRepository users=mock(UserRepository.class);SubscriptionRepository subscriptions=mock(SubscriptionRepository.class);User user=new User(1,"u","n",false,SourceType.ORGANIC,null,null,"r",false,Instant.now(),Instant.now());when(users.findById(1)).thenReturn(Optional.of(user));service(users,subscriptions,mock(AnalyticsRepository.class)).ban(1);verify(users).setBanned(1,true);verify(subscriptions).revoke(1);}
 @Test void analyticsHandlesZeroDenominators(){AnalyticsRepository repository=mock(AnalyticsRepository.class);when(repository.summary(null)).thenReturn(new AnalyticsRepository.Summary(0,0,0,0,0,0,0,BigDecimal.ZERO));when(repository.campaigns(null)).thenReturn(List.of());when(repository.users(null)).thenReturn(List.of());var result=service(mock(UserRepository.class),mock(SubscriptionRepository.class),repository).analytics("all");assertThat(result.startToHapp()).isZero();assertThat(result.happToVpn()).isZero();assertThat(result.vpnToPaid()).isZero();}
 @Test void grantUsesTariffDurationWhenDaysAreEmpty(){UserRepository users=mock(UserRepository.class);TariffRepository tariffs=mock(TariffRepository.class);SubscriptionService subscriptions=mock(SubscriptionService.class);User user=new User(1,"u","n",false,SourceType.ORGANIC,null,null,"r",false,Instant.now(),Instant.now());Tariff tariff=new Tariff(5,"BASIC_12M","12 месяцев",365,BigDecimal.TEN,10,null,UUID.randomUUID(),true,1);when(users.findById(1)).thenReturn(Optional.of(user));when(tariffs.findById(5)).thenReturn(Optional.of(tariff));service(users,mock(SubscriptionRepository.class),mock(AnalyticsRepository.class),tariffs,subscriptions).grant(1,5,null);verify(subscriptions).grant(1,5,365);}
 private AdminService service(UserRepository users,SubscriptionRepository subscriptions,AnalyticsRepository analytics){return new AdminService(users,subscriptions,mock(TariffRepository.class),mock(SubscriptionService.class),mock(PaymentRepository.class),mock(CampaignRepository.class),mock(com.abcvpn.telegram.TelegramClient.class),mock(PaymentService.class),mock(DeviceService.class),mock(VpnAccessService.class),analytics,mock(ReferralService.class));}
 private AdminService service(UserRepository users,SubscriptionRepository repository,AnalyticsRepository analytics,TariffRepository tariffs,SubscriptionService subscriptions){return new AdminService(users,repository,tariffs,subscriptions,mock(PaymentRepository.class),mock(CampaignRepository.class),mock(com.abcvpn.telegram.TelegramClient.class),mock(PaymentService.class),mock(DeviceService.class),mock(VpnAccessService.class),analytics,mock(ReferralService.class));}
}
